#!/bin/sh
# Adapt the vendored toywasm tree to R's build rules and CRAN's checks.
#
# Run from the package root by tools/vendor-toywasm.sh, after the upstream
# copy and before checksums are recorded.
#
# Each change is a substitution rather than a context diff: a .patch breaks
# on any nearby upstream edit, while a substitution either still matches or
# visibly stops matching. `apply` fails the run if a pattern matches nothing,
# so an upstream change can't silently undo a fix.
set -eu

DEST="src/toywasm"
[ -d "$DEST" ] || { echo "patch-for-r: no $DEST" >&2; exit 1; }

# apply FILE PERL-SUBSTITUTION DESCRIPTION
apply () {
  file="$DEST/$1"
  before="$(cat "$file")"
  perl -0777 -pi -e "$2" "$file"
  if [ "$before" = "$(cat "$file")" ]; then
    echo "patch-for-r: no match in $1 for: $3" >&2
    exit 1
  fi
}

# ------------------------------------------------------------------ assert
# R CMD check rejects compiled code that references abort(), and a live
# assert() calls it. NDEBUG alone compiles assertions out, but then every
# variable that only an assertion reads becomes -Wunused-variable or
# -Wunused-but-set-variable (a dozen of them), and CRAN reads compiler
# warnings. This header keeps each assertion's operands "used" through
# sizeof, which never evaluates them, so it has no runtime cost and no
# side effects.
cat > "$DEST/nanowasm_assert.h" <<'HEADER'
/* Generated by tools/vendor/patch-for-r.sh -- do not edit by hand. */
#if !defined(NANOWASM_ASSERT_H)
#define NANOWASM_ASSERT_H

/* Replaces <assert.h> for the vendored toywasm sources. The expression is
   type-checked and its operands count as used, but it is never evaluated
   and nothing can call abort(). The fuzz target (tools/fuzz/) defines
   NANOWASM_REAL_ASSERT to get the real assertions back. */
#if defined(NANOWASM_REAL_ASSERT)
#include <assert.h>
#else
#undef assert
#define assert(e) ((void)sizeof((e) ? 1 : 0))
#endif

#endif /* !defined(NANOWASM_ASSERT_H) */
HEADER

for f in "$DEST"/*.c "$DEST"/*.h; do
  case "$f" in */nanowasm_assert.h) continue;; esac
  if grep -q '#include <assert.h>' "$f"; then
    apply "$(basename "$f")" 's/#include <assert\.h>/#include "nanowasm_assert.h"/g' \
      'assert.h include'
  fi
done

# ------------------------------------------------- statement expressions
# decode.h has a type-checked variant of read_vec_with_ctx built on a GNU
# statement expression, used whenever toywasm_typeof exists (GCC and clang).
# -pedantic warns about every expansion, and CRAN compiles with -pedantic.
# Upstream provides a portable fallback for compilers without typeof; always
# use it.
apply decode.h \
  's/#if defined\(toywasm_typeof\)\n(\/\* a version with non-standard checks \*\/)/#if 0 \/* nanowasm: GNU statement expressions warn under -pedantic *\/\n$1/' \
  'read_vec_with_ctx statement expression'

# ------------------------------------------------------ upstream build bug
# module_print_stats() declares code_size only when TOYWASM_ENABLE_WRITER is
# defined, but uses it unconditionally. The writer is off here, so the file
# does not compile. expr_end() is always available, so declare it always.
apply module.c \
  's/#if defined\(TOYWASM_ENABLE_WRITER\)\n(\s+size_t code_size = 0;)\n#endif\n/$1\n/' \
  'code_size declaration in module_print_stats'

# ---------------------------------------------------------------- Windows
# report.c defines its own vasprintf() on _WIN32, but mingw-w64 (Rtools)
# already provides one in <stdio.h>, so the build fails with "redefinition
# of 'vasprintf'". Keep the fallback for other Windows toolchains only.
apply report.c \
  's/#if defined\(_WIN32\)\nint\nvasprintf/#if defined(_WIN32) && !defined(__MINGW32__)\nint\nvasprintf/' \
  'vasprintf fallback on mingw'

# On mingw, format(printf) means the Microsoft runtime's printf, which gcc
# believes has no %zu, so every size_t in a log format warns (-Wformat).
# The strings go through mingw's own C99-conforming vasprintf, so check
# them as gnu_printf there.
apply platform.h \
  's/#define __printflike\(a, b\) __attribute__\(\(__format__\(__printf__, a, b\)\)\)/#if defined(__MINGW32__)\n#define __printflike(a, b) __attribute__((__format__(__gnu_printf__, a, b)))\n#else\n#define __printflike(a, b) __attribute__((__format__(__printf__, a, b)))\n#endif/' \
  '__printflike on mingw'

# ---------------------------------------------------- gcc -Wmaybe-uninitialized
# gcc cannot see that these out-parameters are always written when the call
# succeeds, and warns at -O2. Initialising them changes nothing at runtime.
apply module.c \
  's/(\n\s+)size_t sz;(\n\s+int ret = cellidx_bytesize\(n, &sz\);)/$1size_t sz = 0;$2/g' \
  'cellidx_bytesize out-parameter'
apply context.c \
  's/(\n\s+)struct resulttype \*p;(\n\s+uint32_t i;\n\s+int ret = resulttype_alloc0\(mctx, ntypes, &p\);)/$1struct resulttype *p = NULL;$2/' \
  'resulttype_alloc0 out-parameter'

# ------------------------------------------------ UBSan: NULL + 0, memset(NULL)
# toywasm's vectors start out NULL and are allocated on first use, and much
# of the interpreter computes addresses such as &v.p[v.lsize] from them
# (the next free stack cell, a frame's locals) even when they are still
# empty. For a NULL p that is NULL + 0, undefined behaviour that CRAN's
# clang-UBSAN check reports ("applying zero offset to null pointer"). Give
# every execution vector one preallocated element up front, so its pointer
# is never NULL; that fixes all those sites at once. An allocation failure
# here only leaves the old behaviour in place.
apply exec.c \
  's/(\n\s+ctx->check_interval = CHECK_INTERVAL_DEFAULT;\n\s+exec_options_set_defaults\(&ctx->options\);\n)/$1        int nw_ret = VEC_PREALLOC(mctx, ctx->frames, 1);\n        nw_ret = VEC_PREALLOC(mctx, ctx->stack, 1);\n        nw_ret = VEC_PREALLOC(mctx, ctx->labels, 1);\n#if defined(TOYWASM_USE_SEPARATE_LOCALS)\n        nw_ret = VEC_PREALLOC(mctx, ctx->locals, 1);\n#endif\n        (void)nw_ret;\n/' \
  'preallocate the execution vectors in exec_context_init()'

# The cell helpers pass their pointers to memset/memcpy, which must not see
# NULL even with a zero length.
apply cell.c \
  's/(cells_zero\(struct cell \*cells, uint32_t ncells\)\n\{\n)/$1        if (ncells == 0) {\n                return;\n        }\n/' \
  'cells_zero() of zero cells'
apply cell.c \
  's/(cells_copy\(struct cell \*restrict dst, const struct cell \*restrict src,\n\s+uint32_t ncells\)\n\{\n)/$1        if (ncells == 0) {\n                return;\n        }\n/' \
  'cells_copy() of zero cells'

# ARRAY_FOREACH (and so VEC_FOREACH) computes a + sz for its end pointer,
# which is NULL + 0 for an empty vector that was never allocated. Stop
# before computing it when the array is NULL.
apply util.h \
  's/#define ARRAY_FOREACH\(p, a, sz\) for \(p = a; p < a \+ sz; p\+\+\)/#define ARRAY_FOREACH(p, a, sz) for (p = a; p != NULL && p < a + sz; p++)/' \
  'ARRAY_FOREACH over a NULL array'

# ------------------------------------------------------------ end state
# Guard against what the rewrites above exist to remove.
if grep -n '#include <assert.h>' "$DEST"/*.c "$DEST"/*.h | grep -v 'nanowasm_assert.h'; then
  echo "patch-for-r: <assert.h> still included" >&2
  exit 1
fi
